<script>
$('#report-customer').select2({width:'100%',placeholder:'All Customers',allowClear:true,minimumInputLength:2,ajax:{url:{{ Illuminate\Support\Js::from(route('admin.reports.sales.customers')) }},dataType:'json',delay:300,data:params=>({q:params.term}),processResults:data=>({results:data.results})}});
document.querySelectorAll('[data-report-range]').forEach(button=>button.addEventListener('click',()=>{
    const today={{ Illuminate\Support\Js::from(now('Asia/Dhaka')->toDateString()) }};
    let from=today,to=today;
    if(button.dataset.reportRange==='yesterday'){const date=new Date(today+'T12:00:00Z');date.setUTCDate(date.getUTCDate()-1);from=to=date.toISOString().slice(0,10);}
    if(button.dataset.reportRange==='month')from=today.slice(0,7)+'-01';
    if(button.dataset.reportRange==='year')from=today.slice(0,4)+'-01-01';
    const form=button.closest('form');form.querySelector('[name=all_time]').checked=false;document.getElementById('report-from').value=from;document.getElementById('report-to').value=to;form.requestSubmit();
}));
</script>
